function section(title: string, content: string, quiet = false): PrayerSection {
  return { title, content, kind: 'mass', quiet }
}

function options(title: string, alternatives: Array<{ label: string; content: string }>, quiet = false): PrayerSection {
  return { title, alternatives, kind: 'mass', quiet }
}

export function massPart(title: string): PrayerSection {
  return { title, kind: 'part', quiet: true }
}

export function isGoodFridayCelebration(settings: PrayerBuildSettings): boolean {
  return calendarText(settings).includes('viernes santo')
}

export function isHolyThursdayCelebration(settings: PrayerBuildSettings): boolean {
  const text = calendarText(settings)

  return text.includes('jueves de semana santa') || text.includes('jueves santo') || text.includes('cena del senor')
}

export function isAshWednesdayCelebration(settings: PrayerBuildSettings): boolean {
  return calendarText(settings).includes('miercoles de ceniza')
}

export function isPalmSundayCelebration(settings: PrayerBuildSettings): boolean {
  const text = calendarText(settings)

  return text.includes('domingo de ramos') || (text.includes('ramos') && text.includes('pasion'))
}

export function isChrismMassCelebration(settings: PrayerBuildSettings): boolean {
  return calendarText(settings).includes('crismal')
}

export function isEasterVigilCelebration(settings: PrayerBuildSettings): boolean {
  const text = calendarText(settings)

  return text.includes('sabado santo') || text.includes('vigilia pascual')
}

function shouldUseEasterDismissal(settings: PrayerBuildSettings): boolean {
  const text = calendarText(settings)

  return (
    isEasterVigilCelebration(settings) ||
    isDateInEasterOctave(settings.date) ||
    text.includes('pentecost') ||
    text.includes('domingo de pascua') ||
    text.includes('octava de pascua')
  )
}

