export function goodFridayCommunionSections(
  settings: PrayerBuildSettings,
  songSection: SongSectionFactory,
): PrayerSection[] {
  const sections: PrayerSection[] = [
    massPart('Rito de la comunión'),
    section('Traslado del Santísimo Sacramento', GOOD_FRIDAY_COMMUNION_PREPARATION, true),
    section('Padrenuestro e invitación a la comunión', goodFridayCommunionRite(settings), true),
  ]

  addSong(sections, settings, songSection, 'comunion')
  sections.push(
    section('Comunión de los fieles', GOOD_FRIDAY_COMMUNION_OF_FAITHFUL, true),
    section('Oración después de la comunión', GOOD_FRIDAY_POST_COMMUNION, true),
    section('Oración sobre el pueblo y salida en silencio', GOOD_FRIDAY_PRAYER_OVER_PEOPLE, true),
  )

  return sections
}

