function palmSundayEntryGospelSection(settings: PrayerBuildSettings): PrayerSection {
  const cycle = settings.cycle?.trim().toUpperCase()
  const alternatives = [
    { label: 'Año A', cycle: 'A', content: PALM_SUNDAY_ENTRY_GOSPEL_A },
    { label: 'Año B', cycle: 'B', content: PALM_SUNDAY_ENTRY_GOSPEL_B },
    { label: 'Año B - Juan', cycle: 'B', content: PALM_SUNDAY_ENTRY_GOSPEL_B_JOHN },
    { label: 'Año C', cycle: 'C', content: PALM_SUNDAY_ENTRY_GOSPEL_C },
  ]
  const ordered = [
    ...alternatives.filter((alternative) => alternative.cycle === cycle),
    ...alternatives.filter((alternative) => alternative.cycle !== cycle),
  ]

  return options(
    'Evangelio de la entrada del Señor',
    ordered.map(({ label, content }) => ({ label, content })),
    true,
  )
}

