function sequenceForSettings(settings: PrayerBuildSettings): { label: string; content: string; required: boolean } | undefined {
  const text = calendarText(settings)
  const daysSinceEaster = daysSinceEasterSunday(settings.date)

  if (text.includes('pentecost')) {
    return { label: 'Pentecostés', content: PENTECOST_SEQUENCE, required: true }
  }

  if (daysSinceEaster !== undefined && daysSinceEaster >= 0 && daysSinceEaster <= 7) {
    return { label: 'Pascua', content: EASTER_SEQUENCE, required: daysSinceEaster === 0 }
  }

  if (text.includes('corpus') || text.includes('cuerpo y sangre')) {
    return { label: 'Corpus Christi', content: CORPUS_SEQUENCE_SHORT, required: false }
  }

  if (text.includes('dolores') && (text.includes('maria') || text.includes('virgen'))) {
    return { label: 'Nuestra Señora de los Dolores', content: STABAT_MATER_SEQUENCE, required: false }
  }

  return undefined
}

function addSong(sections: PrayerSection[], settings: PrayerBuildSettings, songSection: SongSectionFactory, key: MassSongSectionKey): void {
  if (settings.choirMode) {
    sections.push(songSection(key))
  }
}

export function massSequenceSection(settings: PrayerBuildSettings): PrayerSection | undefined {
  const sequence = sequenceForSettings(settings)

  if (!sequence) {
    return undefined
  }

  return section(
    'Secuencia',
    [
      `$Rúbrica.$ ${sequence.required ? 'Obligatoria' : 'Opcional'} en ${sequence.label}; se canta antes del Aleluya.`,
      sequence.content,
    ].join('\n\n'),
    true,
  )
}

export function massGospelAcclamationSection(settings: PrayerBuildSettings): PrayerSection {
  const commonVerse = commonGospelAcclamationVerse(settings)

  return options(
    'Aclamación antes del Evangelio',
    [
      {
        label: commonVerse.label,
        content: acclamationBlock(settings, commonVerse.verse),
      },
      {
        label: 'Omitida',
        content:
          '$Rúbrica.$ Si no se canta, el Aleluya o el versículo antes del Evangelio puede omitirse según la Instrucción General del Misal Romano.',
      },
    ],
    true,
  )
}

