function normalize(value: string): string {
  const romanNumerals: Record<string, string> = {
    i: '1',
    ii: '2',
    iii: '3',
    iv: '4',
    v: '5',
    vi: '6',
    vii: '7',
    viii: '8',
    ix: '9',
    x: '10',
    xi: '11',
    xii: '12',
    xiii: '13',
    xiv: '14',
    xv: '15',
    xvi: '16',
    xvii: '17',
    xviii: '18',
    xix: '19',
    xx: '20',
    xxi: '21',
    xxii: '22',
    xxiii: '23',
    xxiv: '24',
    xxv: '25',
    xxvi: '26',
    xxvii: '27',
    xxviii: '28',
    xxix: '29',
    xxx: '30',
    xxxi: '31',
    xxxii: '32',
    xxxiii: '33',
    xxxiv: '34',
  }

  return value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .split(/\s+/)
    .map((token) => romanNumerals[token] ?? token)
    .join(' ')
}

function ordinaryWeekFallbackContext(celebration?: string): string {
  const normalizedCelebration = normalize(celebration ?? '')
  const match = normalizedCelebration.match(
    /\b(?:lunes|martes|miercoles|jueves|viernes|sabado)\b.*\b(\d{1,2})\b.*\bsemana\b.*\btiempo\b.*\bordinario\b/,
  )

  if (!match) {
    return ''
  }

  const week = match[1]

  return `ordinary time ${week} sunday ${week} domingo del tiempo ordinario`
}

function christmasWeekdayFallbackContext(settings: MissalSettingsContext): string {
  if (!settings.date) {
    return ''
  }

  const normalizedCelebration = normalize(settings.celebration ?? '')
  if (!/^\d{1,2} de enero$/.test(normalizedCelebration)) {
    return ''
  }

  const weekdays = ['domingo', 'lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado']
  const weekday = weekdays[settings.date.getDay()]

  return `${weekday} del tiempo de navidad`
}

function fixedDateContext(settings: MissalSettingsContext): string {
  if (!settings.date) {
    return ''
  }

  const months = [
    'enero',
    'febrero',
    'marzo',
    'abril',
    'mayo',
    'junio',
    'julio',
    'agosto',
    'septiembre',
    'octubre',
    'noviembre',
    'diciembre',
  ]

  return `${settings.date.getDate()} de ${months[settings.date.getMonth()]}`
}

function englishRoleFallbackContext(celebration?: string): string {
  const normalizedCelebration = normalize(celebration ?? '')

  if (!normalizedCelebration || /\b(?:christ|jesus|lord|god)\b/.test(normalizedCelebration)) {
    return ''
  }

  const rolePairs: Array<[RegExp, string]> = [
    [/\bsaints?\b/, 'santo santa santos santas'],
    [/\bmartyrs?\b/, 'martir martires'],
    [/\bbishops?\b/, 'obispo'],
    [/\bpopes?\b/, 'papa'],
    [/\bpriests?\b|\bpresbyters?\b/, 'presbitero'],
    [/\bvirgins?\b/, 'virgen'],
    [/\breligious\b/, 'religioso religiosa'],
    [/\babbots?\b/, 'abad'],
    [/\babbesses?\b/, 'abadesa'],
    [/\bmonks?\b/, 'monje'],
    [/\bnuns?\b/, 'monja'],
  ]

  return rolePairs
    .filter(([pattern]) => pattern.test(normalizedCelebration))
    .map(([, fallback]) => fallback)
    .join(' ')
}

function contextText(settings: MissalSettingsContext): string {
  return normalize(
    [
      settings.celebration,
      fixedDateContext(settings),
      englishRoleFallbackContext(settings.celebration),
      ordinaryWeekFallbackContext(settings.celebration),
      christmasWeekdayFallbackContext(settings),
      settings.rank,
      ...(settings.seasons ?? []),
    ]
      .filter(Boolean)
      .join(' '),
  )
}

export function localProperAlternatives(field: MissalProperField, settings: MissalSettingsContext): MissalProperEntry[] {
  const context = contextText(settings)

  if (!context) {
    return []
  }

  const strongestSpecificProper = Math.max(
    ...LOCAL_PROPERS
      .filter((entry) => !entry.title.startsWith('Común') && entry.fields[field])
      .map((entry) => properSpecificity(entry, context)),
    0,
  )

  const matches = LOCAL_PROPERS.filter((entry) => {
    if (!entry.fields[field]) {
      return false
    }

    const specificity = properSpecificity(entry, context)

    if (!specificity) {
      return false
    }

    return entry.title.startsWith('Común') || !strongestSpecificProper || specificity >= strongestSpecificProper
  })

  const exactMatches = matches.filter((entry) => !entry.title.startsWith('Común'))

  return (exactMatches.length ? exactMatches : matches).sort(
    (left, right) => properSpecificity(right, context) - properSpecificity(left, context),
  )
}

function properSpecificity(entry: MissalProperEntry, context: string): number {
  return Math.max(
    ...entry.aliases.map((alias) => {
      const normalizedAlias = normalize(alias)

      if (!normalizedAlias) {
        return 0
      }

      if (context.includes(normalizedAlias)) {
        return normalizedAlias.length
      }

      if (normalizedAlias.includes(context)) {
        return context.length
      }

      return 0
    }),
    0,
  )
}
