import { Capacitor, registerPlugin } from '@capacitor/core'

/**
 * Grabación de pantalla NATIVA (Android) con micrófono, vía el cascarón Capacitor de la app
 * (ver capacitor.config.ts en la raíz del repo y app/android/). Solo existe cuando la app corre
 * dentro del APK: en el navegador/PWA `isNativeScreenRecorderAvailable()` es false y la app
 * sigue con su flujo de siempre (grabador nativo del móvil arrancado a mano por Lucas).
 *
 * Por qué: desde una web no hay forma de disparar el grabador de pantalla del sistema ni de saber
 * si el micrófono está activo — y en Android dos apps no pueden capturar audio a la vez, así que
 * "comprobar el mic" desde la web dejaría muda la grabación nativa. Grabando desde el propio APK,
 * con `recordAudio: true`, el micrófono va SIEMPRE dentro del vídeo: el problema de "grabé sin
 * micro" desaparece de raíz, sin detección. Ver memoria de proyecto idea-capacitor-grabar-pantalla.
 */

interface ScreenRecorderPlugin {
  start(options?: { recordAudio?: boolean; format?: 'mp4' | 'mov' }): Promise<void>
  stop(): Promise<void>
  getPluginVersion(): Promise<{ version: string }>
}

// Nombre registrado por @capgo/capacitor-screen-recorder en el lado nativo. Se registra a mano
// (en vez de importar el paquete) para que el bundle web no arrastre nada nativo: cuando no hay
// cascarón, ninguna llamada llega a hacerse.
const ScreenRecorder = registerPlugin<ScreenRecorderPlugin>('ScreenRecorder')

export function isNativeScreenRecorderAvailable(): boolean {
  return Capacitor.isNativePlatform() && Capacitor.isPluginAvailable('ScreenRecorder')
}

/** Lanza la grabación nativa con micrófono. Android muestra el diálogo del sistema "¿permitir
 * grabar la pantalla?" en cada grabación — no se puede evitar. Rechaza si Lucas lo cancela. */
export async function startNativeScreenRecording(): Promise<void> {
  await ScreenRecorder.start({ recordAudio: true, format: 'mp4' })
}

/** Detiene la grabación; el mp4 queda guardado en la galería del móvil. */
export async function stopNativeScreenRecording(): Promise<void> {
  await ScreenRecorder.stop()
}
