<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { ChevronLeft, ChevronRight, Search } from '@lucide/vue'

import {
  chapterVerses,
  filterBooks,
  findBook,
  findChapter,
  isBibleLoaded,
  loadBible,
  type BibleBook,
} from '../lib/bible'

/**
 * La Biblia de Jerusalén, con los mismos tres niveles que en Breviarium: lista de
 * libros con buscador → rejilla de capítulos → capítulo con los versículos numerados
 * y salto al anterior/siguiente.
 *
 * La navegación no vive aquí: `book` y `chapter` llegan como props desde App.vue, que
 * es quien empuja cada nivel al historial del navegador. Así el botón "atrás" de
 * Android retrocede capítulo → libro → índice → inicio, en vez de tirar de la app
 * entera al primer toque.
 */
const props = defineProps<{
  book: string | null
  chapter: string | null
}>()

const emit = defineEmits<{
  (event: 'select-book', book: string): void
  (event: 'select-chapter', chapter: string): void
  (event: 'back'): void
}>()

const books = ref<BibleBook[]>([])
const loading = ref(!isBibleLoaded())
const error = ref('')
const query = ref('')

onMounted(async () => {
  try {
    books.value = await loadBible()
  } catch {
    error.value = 'No se pudo cargar la Biblia. Comprueba la conexión y vuelve a entrar.'
  } finally {
    loading.value = false
  }
})

const visibleBooks = computed(() => filterBooks(books.value, query.value))
const oldTestament = computed(() => visibleBooks.value.filter((item) => item.testament === 'Antiguo'))
const newTestament = computed(() => visibleBooks.value.filter((item) => item.testament === 'Nuevo'))

const currentBook = computed(() => (props.book ? findBook(books.value, props.book) : undefined))
const currentChapter = computed(() => {
  const book = currentBook.value
  return book && props.chapter ? findChapter(book, props.chapter) : undefined
})
const verses = computed(() => (currentChapter.value ? chapterVerses(currentChapter.value) : []))

/** Índice del capítulo abierto dentro del libro, para saber si hay anterior y siguiente. */
const chapterIndex = computed(() => {
  const book = currentBook.value
  if (!book || !props.chapter) {
    return -1
  }
  return book.chapters.findIndex((item) => item.chapter === props.chapter)
})

const previousChapter = computed(() => {
  const book = currentBook.value
  return book && chapterIndex.value > 0 ? book.chapters[chapterIndex.value - 1].chapter : null
})

const nextChapter = computed(() => {
  const book = currentBook.value
  if (!book || chapterIndex.value < 0 || chapterIndex.value >= book.chapters.length - 1) {
    return null
  }
  return book.chapters[chapterIndex.value + 1].chapter
})

const level = computed<'books' | 'chapters' | 'verses'>(() => {
  if (props.book && props.chapter) {
    return 'verses'
  }
  return props.book ? 'chapters' : 'books'
})

const heading = computed(() => {
  if (level.value === 'books') {
    return 'Biblia de Jerusalén'
  }
  const name = currentBook.value?.name ?? props.book ?? ''
  return level.value === 'verses' ? `${name} ${props.chapter}` : name
})

// Cada cambio de nivel empieza arriba: al abrir un capítulo nuevo no se hereda el
// desplazamiento del anterior (saltar de Salmo 118 a 119 dejaba la vista a media página).
watch(level, () => window.scrollTo({ top: 0, behavior: 'auto' }))
watch(() => props.chapter, () => window.scrollTo({ top: 0, behavior: 'auto' }))
</script>

<template>
  <article class="reader-surface bible-surface">
    <div class="bible-header">
      <button type="button" class="icon-button" aria-label="Volver" @click="emit('back')">
        <ChevronLeft :size="22" />
      </button>
      <div>
        <p class="kicker">Biblia</p>
        <h1>{{ heading }}</h1>
      </div>
    </div>

    <div v-if="loading" class="loading-state">
      <span />
      Cargando la Biblia
    </div>

    <div v-else-if="error" class="empty-state">
      {{ error }}
    </div>

    <template v-else-if="level === 'books'">
      <label class="bible-search">
        <Search :size="18" />
        <input v-model="query" type="search" placeholder="Buscar libro" aria-label="Buscar libro" />
      </label>

      <p v-if="!visibleBooks.length" class="empty-state">Ningún libro coincide con «{{ query }}».</p>

      <template v-for="group in [
        { title: 'Antiguo Testamento', items: oldTestament },
        { title: 'Nuevo Testamento', items: newTestament },
      ]" :key="group.title">
        <section v-if="group.items.length" class="bible-group">
          <p class="section-eyebrow">{{ group.title }}</p>
          <ul class="bible-book-list">
            <li v-for="item in group.items" :key="item.name">
              <button type="button" class="bible-book" @click="emit('select-book', item.name)">
                <span>{{ item.name }}</span>
                <small>{{ item.abbreviation }}</small>
              </button>
            </li>
          </ul>
        </section>
      </template>
    </template>

    <template v-else-if="level === 'chapters'">
      <div v-if="currentBook" class="chapter-grid">
        <button
          v-for="item in currentBook.chapters"
          :key="item.chapter"
          type="button"
          class="chapter-box"
          @click="emit('select-chapter', item.chapter)"
        >
          {{ item.chapter }}
        </button>
      </div>
      <p v-else class="empty-state">No se encontró el libro «{{ props.book }}».</p>
    </template>

    <template v-else>
      <div v-if="verses.length" class="bible-text">
        <p v-for="verse in verses" :key="verse.number">
          <small class="verse-number">{{ verse.number }}</small>
          {{ verse.text }}
        </p>
      </div>
      <p v-else class="empty-state">No se encontró ese capítulo.</p>

      <div class="chapter-nav">
        <button
          type="button"
          class="text-button"
          :disabled="!previousChapter"
          @click="previousChapter && emit('select-chapter', previousChapter)"
        >
          <ChevronLeft :size="18" />
          Anterior
        </button>
        <button
          type="button"
          class="text-button"
          :disabled="!nextChapter"
          @click="nextChapter && emit('select-chapter', nextChapter)"
        >
          Siguiente
          <ChevronRight :size="18" />
        </button>
      </div>
    </template>
  </article>
</template>
