import type { SingingNotationMode } from './text'

/**
 * Repertorio de melodías que Lucas usa para cantar Laudes, con su capo y acordes
 * habituales (de una nota de Keep). Sirve a dos cosas: el ChantPicker de
 * PrayerSection.vue (icono que cicla de cántico, numerito de capo que cicla aparte)
 * y, más adelante, el generador de descripción del vídeo de YouTube.
 *
 * El número de voces (SingingNotationMode) de cada melodía es el número de grupos
 * de acordes separados por "/" — coincide con cuántas partes/voces alternan cantando
 * cada verso. Las partes sin un patrón de voces aplicable (Invocación, Padrenuestro)
 * no llevan `voices`.
 */
export interface ChantVariant {
  key: string
  label: string
  capo: number
  voices?: SingingNotationMode
  chords: string
  /** Nombre de un icono de @lucide/vue (ver CHANT_ICONS en PrayerSection.vue). */
  icon: string
}

const HYMN_CHANTS: ChantVariant[] = [
  { key: 'greg', label: 'Gregoriano', capo: 1, voices: 3, chords: 'DO SOL / DO la / FA SOL DO', icon: 'Scroll' },
  { key: 'desc', label: 'Descendente', capo: 1, voices: 4, chords: 'DO / la / FA re / SOL', icon: 'TrendingDown' },
]

// "Cuartas" (4 voces) y "Segundas" (2 voces): familias de tono para los tres salmos.
// Cualquiera de los tres salmos puede llevar cualquiera de estas 8 melodías.
const PSALM_CHANTS: ChantVariant[] = [
  { key: 'tatotaton', label: 'Tatotatón', capo: 4, voices: 4, chords: 'la / SOL DO / la / FA mi la', icon: 'ChevronsDown' },
  { key: 'tatitaton', label: 'Tatitatón', capo: 3, voices: 2, chords: 'la / DO SOL (flexa: la SOL)', icon: 'ChevronsUp' },
  { key: 'clasica', label: 'Clásica', capo: 4, voices: 2, chords: 'la DO / re MI la (flexa: la SOL)', icon: 'Landmark' },
  { key: 'arabe', label: 'Árabe', capo: 3, voices: 2, chords: 're la / SOL re (flexa: re DO)', icon: 'MoonStar' },
  { key: 'rota', label: 'Rota', capo: 5, voices: 2, chords: 'DO SOL la / FA SOL DO (flexa: DO FA)', icon: 'Unlink' },
  { key: 'ascendente', label: 'Ascendente', capo: 1, voices: 4, chords: 'DO SOL / SOL la / la FA / FA SOL', icon: 'TrendingUp' },
  { key: 'epica', label: 'Épica', capo: 5, voices: 4, chords: 'DO SOL la / mi re / FA re / re SOL DO', icon: 'Swords' },
  { key: 'narnia', label: 'Narnia', capo: 1, voices: 4, chords: 'si MI / MI si / RE LA / fa# si', icon: 'Snowflake' },
]

// Partes con un único acorde/capo (sin variantes entre las que elegir): el ChantPicker
// muestra igualmente el icono (fijo, no cicla) y el numerito de capo (sí cicla).
const INVOCATION_CHANTS: ChantVariant[] = [
  { key: 'invocacion', label: 'Invocación inicial', capo: 1, chords: 'mi (si) / DO RE / mi DO mi / DO mi / DO RE mi (RE mi)', icon: 'Flame' },
]
const RESPONSORY_CHANTS: ChantVariant[] = [
  { key: 'responsorio', label: 'Responsorio breve', capo: 3, voices: 2, chords: 'RE LA / SOL RE', icon: 'MessageSquare' },
]
const ZACHARY_CANTICLE_CHANTS: ChantVariant[] = [
  { key: 'zacarias', label: 'Cántico de Zacarías', capo: 2, voices: 4, chords: 'DO SOL / mi la / FA DO / re SOL DO', icon: 'Mic2' },
]
const LORD_PRAYER_CHANTS: ChantVariant[] = [
  {
    key: 'padrenuestro',
    label: 'Padrenuestro',
    capo: 1,
    chords: 'DO FA DO / DO SOL DO / DO FA DO / DO SOL mi SOL la / DO FA DO / DO SOL mi SOL la / FA DO / DO SOL DO',
    icon: 'Users',
  },
]

/** Título de sección (en Laudes) -> pool de melodías entre las que cicla el ChantPicker. */
export const LAUDES_CHANT_POOLS: Record<string, ChantVariant[]> = {
  'Invocación inicial': INVOCATION_CHANTS,
  Himno: HYMN_CHANTS,
  'Primer salmo': PSALM_CHANTS,
  'Segundo salmo': PSALM_CHANTS,
  'Tercer salmo': PSALM_CHANTS,
  'Responsorio breve': RESPONSORY_CHANTS,
  'Cántico de Zacarías': ZACHARY_CANTICLE_CHANTS,
  Padrenuestro: LORD_PRAYER_CHANTS,
}

/** Título de sección (en Laudes) -> key del cántico por defecto de ese día tipo. */
export const LAUDES_CHANT_DEFAULTS: Record<string, string> = {
  'Invocación inicial': 'invocacion',
  Himno: 'greg',
  'Primer salmo': 'tatotaton',
  'Segundo salmo': 'tatitaton',
  'Tercer salmo': 'ascendente',
  'Responsorio breve': 'responsorio',
  'Cántico de Zacarías': 'zacarias',
  Padrenuestro: 'padrenuestro',
}

export function chantVariant(sectionTitle: string, key: string): ChantVariant | undefined {
  return LAUDES_CHANT_POOLS[sectionTitle]?.find((chant) => chant.key === key)
}
