/**
 * Detección de tono para el afinador de guitarra de la pantalla de inicio.
 *
 * Autocorrelación normalizada (NSDF, McLeod Pitch Method simplificado): más robusta que la
 * autocorrelación cruda frente al armónico dominante de una cuerda pulsada — una 6ª cuerda al
 * aire suele tener el 2º armónico (165 Hz) más fuerte que su fundamental (82 Hz), y una FFT
 * ingenua la afinaría una octava alta.
 *
 * Todo aquí es lógica pura sin Web Audio, para poder probarlo con vitest.
 */

/** Cuerdas de la guitarra al aire, en afinación estándar, de la 6ª a la 1ª. */
export interface GuitarString {
  /** Número de cuerda como lo nombra un guitarrista: 6 es la más grave. */
  number: number
  /** Nombre de la nota en notación anglosajona (la que usa el cifrado de los cánticos). */
  name: string
  /** Nombre en notación latina, para el rótulo grande. */
  latin: string
  frequency: number
}

export const GUITAR_STRINGS: GuitarString[] = [
  { number: 6, name: 'E', latin: 'Mi', frequency: 82.41 },
  { number: 5, name: 'A', latin: 'La', frequency: 110.0 },
  { number: 4, name: 'D', latin: 'Re', frequency: 146.83 },
  { number: 3, name: 'G', latin: 'Sol', frequency: 196.0 },
  { number: 2, name: 'B', latin: 'Si', frequency: 246.94 },
  { number: 1, name: 'E', latin: 'Mi', frequency: 329.63 },
]

/** Margen de afinación en cents dentro del cual se considera la cuerda "en su sitio". */
export const IN_TUNE_CENTS = 5

/** Rango útil: por debajo de la 6ª bajada y por encima de la 1ª subida, todo es ruido. */
const MIN_FREQUENCY = 60
const MAX_FREQUENCY = 500
/** Por debajo de este nivel eficaz se considera silencio (no hay cuerda sonando). */
const MIN_RMS = 0.008
/** Un pico NSDF por debajo de esto es demasiado ambiguo para fiarse. */
const MIN_CLARITY = 0.9

export interface PitchReading {
  frequency: number
  /** 0..1: cuán periódica es la señal en ese periodo. Sirve para descartar ruido. */
  clarity: number
}

/**
 * Devuelve la frecuencia fundamental del buffer, o `null` si es silencio o ruido sin tono.
 */
export function detectPitch(buffer: Float32Array, sampleRate: number): PitchReading | null {
  const size = buffer.length
  if (size < 512) return null

  // Quitar la componente continua: un micrófono con offset falsea la autocorrelación.
  let mean = 0
  for (let i = 0; i < size; i += 1) mean += buffer[i]
  mean /= size

  const signal = new Float32Array(size)
  let sumSquares = 0
  for (let i = 0; i < size; i += 1) {
    const value = buffer[i] - mean
    signal[i] = value
    sumSquares += value * value
  }

  if (Math.sqrt(sumSquares / size) < MIN_RMS) return null

  const minTau = Math.max(2, Math.floor(sampleRate / MAX_FREQUENCY))
  const maxTau = Math.min(size - 1, Math.ceil(sampleRate / MIN_FREQUENCY))
  if (maxTau <= minTau) return null

  // NSDF: n(tau) = 2 * sum(x[i]*x[i+tau]) / sum(x[i]^2 + x[i+tau]^2).
  // Se calcula desde tau=1 y no desde minTau porque pickPeriod necesita ver el cruce por cero
  // de la caída inicial, que en las cuerdas agudas cae ANTES de minTau; arrancar en minTau
  // haría tomar la subida hacia el primer pico por esa caída y saltárselo entero.
  const nsdf = new Float32Array(maxTau + 1)
  for (let tau = 1; tau <= maxTau; tau += 1) {
    let correlation = 0
    let energy = 0
    const window = size - tau
    for (let i = 0; i < window; i += 1) {
      const a = signal[i]
      const b = signal[i + tau]
      correlation += a * b
      energy += a * a + b * b
    }
    nsdf[tau] = energy > 0 ? (2 * correlation) / energy : 0
  }

  const tau = pickPeriod(nsdf, minTau, maxTau)
  if (tau === null) return null

  const refined = refinePeak(nsdf, tau)
  const frequency = sampleRate / refined
  if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) return null

  return { frequency, clarity: Math.min(1, Math.max(0, nsdf[tau])) }
}

/**
 * Elige el periodo: el PRIMER máximo local que llegue al 90 % del máximo absoluto. Quedarse con
 * el máximo absoluto sin más elegiría a menudo un múltiplo del periodo real (media octava abajo).
 */
function pickPeriod(nsdf: Float32Array, minTau: number, maxTau: number): number | null {
  const peaks: number[] = []
  // Sólo se buscan máximos después del primer cruce por cero: la zona inicial es la caída
  // desde n(0)=1 y siempre contiene un "máximo" espurio.
  let tau = 1
  while (tau <= maxTau && nsdf[tau] > 0) tau += 1

  for (; tau < maxTau; tau += 1) {
    if (nsdf[tau] > nsdf[tau - 1] && nsdf[tau] >= nsdf[tau + 1]) {
      if (tau >= minTau) peaks.push(tau)
      // Saltar el resto de esta joroba para no registrar el mismo pico dos veces.
      while (tau < maxTau && nsdf[tau + 1] >= 0) tau += 1
    }
  }

  if (!peaks.length) return null

  let best = peaks[0]
  for (const peak of peaks) {
    if (nsdf[peak] > nsdf[best]) best = peak
  }
  if (nsdf[best] < MIN_CLARITY) return null

  const threshold = nsdf[best] * 0.9
  for (const peak of peaks) {
    if (nsdf[peak] >= threshold) return peak
  }
  return best
}

/** Interpolación parabólica sobre los tres puntos del pico: la resolución entera de tau da
 * saltos de varios cents en las cuerdas agudas, que se verían como una aguja a tirones. */
function refinePeak(nsdf: Float32Array, tau: number): number {
  const previous = nsdf[tau - 1] ?? nsdf[tau]
  const next = nsdf[tau + 1] ?? nsdf[tau]
  const denominator = 2 * (2 * nsdf[tau] - previous - next)
  if (!Number.isFinite(denominator) || denominator === 0) return tau
  const shift = (next - previous) / denominator
  return Math.abs(shift) < 1 ? tau + shift : tau
}

export interface StringMatch {
  string: GuitarString
  /** Desviación respecto a la cuerda al aire, en cents (negativo = baja). */
  cents: number
}

/** Cuerda al aire más cercana a esa frecuencia, medida en distancia logarítmica (musical). */
export function matchGuitarString(frequency: number): StringMatch {
  let best = GUITAR_STRINGS[0]
  let bestCents = centsBetween(frequency, best.frequency)
  for (const string of GUITAR_STRINGS) {
    const cents = centsBetween(frequency, string.frequency)
    if (Math.abs(cents) < Math.abs(bestCents)) {
      best = string
      bestCents = cents
    }
  }
  return { string: best, cents: bestCents }
}

export function centsBetween(frequency: number, reference: number): number {
  return 1200 * Math.log2(frequency / reference)
}
