export function toInputDate(date: Date): string {
  const year = date.getFullYear()
  const month = String(date.getMonth() + 1).padStart(2, '0')
  const day = String(date.getDate()).padStart(2, '0')
  return `${year}-${month}-${day}`
}

export function fromInputDate(value: string): Date {
  const [year, month, day] = value.split('-').map(Number)
  return new Date(year, month - 1, day)
}

export function addDays(value: string, days: number): string {
  const date = fromInputDate(value)
  date.setDate(date.getDate() + days)
  return toInputDate(date)
}

export function formatLongDate(date: Date): string {
  return new Intl.DateTimeFormat('es-ES', {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
    year: 'numeric',
  }).format(date)
}

/** Zona horaria de Lucas (Costa Rica). Sus máquinas y su móvil pueden ir en otra zona (la de
 * Windows corre en Europe/Madrid), así que "hoy" nunca se lee del reloj local a secas. */
export const LUCAS_TIME_ZONE = 'America/Costa_Rica'

export function todayInTimeZone(timeZone = LUCAS_TIME_ZONE, now = new Date()): string {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(now)
  const part = (type: string) => parts.find((item) => item.type === type)?.value ?? '00'
  return `${part('year')}-${part('month')}-${part('day')}`
}

/** La fecha que Lucas REZA hoy: la de mañana en Costa Rica. Reza y graba de víspera (el vídeo del
 * canal se publica a las 21:00 de Costa Rica para la mañana siguiente), y hasta el 01/09/2026
 * adelantaba el día a mano cada noche; pidió que la app arranque directamente ahí y que el botón
 * "Hoy" vuelva ahí. Ver CLAUDE.md, "Reglas duras". */
export function prayedTodayDate(now = new Date()): string {
  return addDays(todayInTimeZone(LUCAS_TIME_ZONE, now), 1)
}

export function formatShortDate(date: Date): string {
  return new Intl.DateTimeFormat('es-ES', {
    day: '2-digit',
    month: 'short',
  }).format(date)
}

/** Hora local (0-23) en la zona indicada, para comparar contra umbrales como "las 04:00". */
export function hourInTimeZone(timeZone = LUCAS_TIME_ZONE, now = new Date()): number {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone,
    hour: 'numeric',
    hourCycle: 'h23',
  }).formatToParts(now)
  const hour = parts.find((item) => item.type === 'hour')?.value
  return hour ? Number(hour) : 0
}

/** Fecha (YYYY-MM-DD) en la zona indicada a la que corresponde un instante ISO en UTC. */
export function dateInTimeZoneFromIso(iso: string, timeZone = LUCAS_TIME_ZONE): string {
  return todayInTimeZone(timeZone, new Date(iso))
}
