import type { ChantVariant } from './chant-catalog'
import { isStandardGloriaPatriStanza, type SingingNotationMode } from './text'

/**
 * Lógica pura del ChantPicker (05/09/2026, Lucas): nunca repetir melodía entre secciones del
 * mismo día, orden de ciclo "familia primero" y heurística de familia preferida por recuento
 * de versos. Extraído de PrayerSection.vue para poder testearlo sin montar el componente —
 * ver [[chant-picker-diseno]] y [[catalogo-canticos-y-capo]].
 */

export interface StanzaLineCountEntry {
  lineCount: number
  occurrences: number
}

/**
 * Cuenta versos por estrofa (estrofas separadas por línea en blanco), ignorando el Gloria al
 * Padre (`isStandardGloriaPatriStanza`) y las marcas de antífona repetida — ya se filtraban así
 * en PrayerSection.vue, aquí solo se extrae para poder testearlo (ver confirmación pedida por
 * Lucas: el Gloria de 3 versos NUNCA debe contaminar el recuento). Devuelve las cantidades
 * distintas de versos ordenadas por número de apariciones (de más a menos) y, en empate, por
 * número de versos (de menor a mayor).
 */
export function computeStanzaLineCountEntries(content: string): StanzaLineCountEntry[] {
  const trimmed = content.trim()
  if (!trimmed) {
    return []
  }

  const rawCounts = trimmed
    .split(/\n{2,}/)
    .map((stanza) => {
      const lines = stanza
        .split(/\r?\n/)
        .map((line) => line.trim())
        .filter((line) => line && !line.startsWith('[[ANTIPHON]]') && !/^\[\[REPEATED_?ANTIPHON\]\]/.test(line))

      return isStandardGloriaPatriStanza(lines) ? 0 : lines.length
    })
    .filter((count) => count > 0)

  const occurrences = new Map<number, number>()
  for (const count of rawCounts) {
    occurrences.set(count, (occurrences.get(count) ?? 0) + 1)
  }

  return [...occurrences.entries()]
    .map(([lineCount, count]) => ({ lineCount, occurrences: count }))
    .sort((a, b) => b.occurrences - a.occurrences || a.lineCount - b.lineCount)
}

/**
 * Familia de tono preferida (4 o 2 voces) a partir del recuento de versos por estrofa (Lucas,
 * 05/09/2026: "si todos son de cuatro menos alguno de tres... también si la mayoría son de dos
 * salvo alguno de tres"). Sin preferencia si no aparece ni el 4 ni el 2, o si ambos empatan en
 * número de apariciones.
 */
export function preferredChantFamily(entries: StanzaLineCountEntry[]): SingingNotationMode | undefined {
  const four = entries.find((entry) => entry.lineCount === 4)
  const two = entries.find((entry) => entry.lineCount === 2)

  if (!four && !two) {
    return undefined
  }
  if (four && two && four.occurrences === two.occurrences) {
    return undefined
  }
  if (!two) {
    return 4
  }
  if (!four) {
    return 2
  }

  return four.occurrences > two.occurrences ? 4 : 2
}

export interface ChantCycleOptions {
  /** Clave del cántico ya seleccionado (nube o localStorage). Si está, va primera en el ciclo
   * y su familia (`voices`) es la que arranca el orden. */
  currentKey?: string
  /** Familia (voces) preferida cuando no hay `currentKey` — ver preferredChantFamily(). */
  preferredFamily?: SingingNotationMode
  /** Claves ya usadas por secciones anteriores de la misma Hora (Lucas, 05/09/2026: "nunca
   * repito dos melodías... dentro del mismo día"). Se excluyen del ciclo salvo que excluirlas
   * dejara el pool vacío, en cuyo caso se cae al pool completo sin excluir. */
  takenKeys?: Iterable<string>
}

/**
 * Orden de ciclo de un pool de cánticos: la actual (o, si no hay actual, la primera disponible
 * de la familia preferida) va primera; después el resto de su misma familia en orden de
 * catálogo; después la otra familia en orden de catálogo; por último se quitan las claves ya
 * tomadas por secciones anteriores (con el blindaje de no dejar el pool vacío).
 */
export function buildChantCycleOrder(pool: ChantVariant[], options: ChantCycleOptions = {}): ChantVariant[] {
  if (!pool.length) {
    return []
  }

  const current = options.currentKey ? pool.find((chant) => chant.key === options.currentKey) : undefined
  const startFamily = current?.voices ?? options.preferredFamily
  const rest = pool.filter((chant) => chant.key !== current?.key)
  const sameFamily = startFamily !== undefined ? rest.filter((chant) => chant.voices === startFamily) : []
  const otherFamily = startFamily !== undefined ? rest.filter((chant) => chant.voices !== startFamily) : rest
  const ordered = current ? [current, ...sameFamily, ...otherFamily] : [...sameFamily, ...otherFamily]

  const taken = new Set(options.takenKeys ?? [])
  if (!taken.size) {
    return ordered
  }

  const filtered = ordered.filter((chant) => !taken.has(chant.key))
  return filtered.length ? filtered : ordered
}
