export type LordPrayerLanguage = 'es' | 'la'
export type ConclusionKind = 'blessing' | 'short' | 'compline'
export type MarianAntiphonKind = 'almaRedemptoris' | 'aveRegina' | 'reginaCaeli' | 'salveRegina'

export const GLORIA = `Gloria al Padre, y al Hijo, y al Espíritu Santo.
Como era en el principio, ahora y siempre, por los siglos de los siglos. Amén.`

export function openingPrayer(isLent: boolean): string {
  return [
    '$V.$ Dios mío, ven en mi auxilio.',
    '$R.$ Señor, date prisa en socorrerme.',
    '$R.$ Gloria al Padre, y al Hijo, y al Espíritu Santo.',
    '$V.$ Como era en el principio, ahora y siempre, por los siglos de los siglos. Amén.',
    isLent ? '' : 'Aleluya.',
  ]
    .filter(Boolean)
    .join('\n\n')
}

