const CONCLUSIONS: Record<ConclusionKind, string> = {
  blessing: `$V.$ El Señor nos bendiga, nos guarde de todo mal y nos lleve a la vida eterna.
$R.$ Amén.`,
  short: `$V.$ Bendigamos al Señor.
$R.$ Demos gracias a Dios.`,
  compline: `$V.$ El Señor todopoderoso nos conceda una noche tranquila y una muerte santa.
$R.$ Amén.`,
}

export function conclusion(kind: ConclusionKind): string {
  return CONCLUSIONS[kind]
}
